-- 2026-11-17 每日收录：和焦虑一起冒险、Astray、0h n0、粒子点击者、Bitburner，均为 embed（站内打开原作）。
-- 只插入，不改已有行；INSERT OR IGNORE 防止与本地 jiwan.sql 重复。

INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('adventures-with-anxiety', '和焦虑一起冒险', 'Adventures With Anxiety!', 'jiaolv maoxian hejiaolvyiqimaoxian anxiety adventures nicky case', 'Nicky Case', '', '', NULL, '', 0, 2020, 'story', '["互动叙事","心理健康","故事"]', 0, 0.1, 'story', 'https://ncase.me/anxiety/', 0, 0, 0, 1, 0, 0, 1, 'mid', 'hosted', '你来扮演那只焦虑的狼', '一则关于人和他的焦虑的互动故事：你扮演焦虑本身，用幽默的方式看看它如何运作。原页有中文等译本。', 'An interactive story about a person and their anxiety: you play as the anxiety, and look at how it works, with humor. Translations, including Chinese, are on the page.', '由 Nicky Case 制作，音乐由 Monplaisir 创作，以公共领域（CC0）发布。原页托管在 ncase.me/anxiety，不是即玩的作品。在即玩里直接打开原作。页侧可切换中文等多种语言。开玩不用登录。', 'Made by Nicky Case with music by Monplaisir, and released into the public domain under CC0. Hosted at ncase.me/anxiety; it is not a Jiwan original. It opens here. Translations, including Chinese, are linked on the page. No account needed.', 'assets/posters/adventures-with-anxiety.jpg', 1280, 800, 'center', '["assets/posters/adventures-with-anxiety.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -23, 1794880800000, 'This time, you play as the anxiety.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('astray', 'Astray', 'Astray', 'astray milu migong webgl wwwtyro rye terrell', 'Rye Terrell (wwwtyro)', '', '', NULL, '', 0, 2012, 'puzzle', '["迷宫","3D","益智"]', 30, 0.08, 'io', 'https://wwwtyro.github.io/Astray/', 0, 0, 0, 1, 0, 0, 1, 'short', 'hosted', '在砖墙迷宫里滚球，别掉进黑暗里', '用键盘推动一颗球，在 WebGL 迷宫里找路、避坑，走进下一关。按住 I 键可看操作说明。', 'Push a ball with the keyboard through a WebGL maze, avoid the pits, and find the next level. Hold I for instructions.', '由 Rye Terrell（wwwtyro）制作，源码以 Unlicense 贡献到公共领域。原页托管在 wwwtyro.github.io/Astray，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Made by Rye Terrell (wwwtyro) and released into the public domain under the Unlicense. Hosted at wwwtyro.github.io/Astray; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/astray.jpg', 1280, 800, 'center', '["assets/posters/astray.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -22, 1794880800000, 'Roll through a brick maze, and don''t fall into the dark.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('0h-n0', '0h n0', '0h n0', 'oh no 0hn0 linghuan luoji q42 martinkool', 'Martin Kool / Q42', '', '', NULL, '', 0, 2018, 'puzzle', '["益智","逻辑","休闲"]', 200, 0.1, 'story', 'https://0hn0.com/', 0, 0, 0, 1, 0, 0, 1, 'short', 'hosted', '蓝点要对上眼，红点会挡住视线', '蓝点要看见同一行或列里的其他蓝点，红点会挡住视线。点格子，把图填完。', 'Blue dots must see the other blue dots in their row or column; red dots block their view. Fill the grid.', '由 Martin Kool / Q42 制作，是 0h h1 的姐妹作，2018 年起在 0hn0.com 公开发布。原页托管在 0hn0.com，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Made by Martin Kool / Q42 as a companion to 0h h1, and published on 0hn0.com since 2018. Hosted at 0hn0.com; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/0h-n0.jpg', 1280, 800, 'center', '["assets/posters/0h-n0.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -21, 1794880800000, 'Blue dots need to see each other; red dots block the view.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('particle-clicker', '粒子点击者', 'Particle Clicker', 'lizi dianjizhe lizidianjizhe particle clicker cern webfest', 'CERN Webfest 2014 团队', '', '', NULL, '', 0, 2014, 'idle', '["放置","科普","物理"]', 8, 0.1, 'clicker', 'https://particle-clicker.web.cern.ch/', 0, 0, 0, 1, 0, 0, 1, 'mid', 'hosted', '点探测器攒数据，一路走过粒子物理史', '在探测器上点击收集数据，雇研究员、升级实验，从早期加速器一路玩到现代粒子物理。', 'Click the detector to collect data, hire researchers and upgrade experiments, from early accelerators through modern particle physics.', '由 CERN Webfest 2014 团队（Igor Babuschkin、Kevin Dungs、Tadej Novak、Gabor Biro、Jiannan Zhang）制作，源码以 MIT 许可在 GitHub 发布。原页托管在 particle-clicker.web.cern.ch，不是即玩的作品。在即玩里直接打开原作。存档保存在浏览器本地，开玩不用登录。', 'Made by the CERN Webfest 2014 team (Igor Babuschkin, Kevin Dungs, Tadej Novak, Gabor Biro, Jiannan Zhang); the source is MIT-licensed on GitHub. Hosted at particle-clicker.web.cern.ch; it is not a Jiwan original. It opens here. Saves stay in your browser; no account needed.', 'assets/posters/particle-clicker.jpg', 1280, 800, 'center', '["assets/posters/particle-clicker.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -20, 1794880800000, 'Click the detector, gather data, and walk through the history of particle physics.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('bitburner', 'Bitburner', 'Bitburner', 'bitburner bitebener hei ke chengxu zengliang daniel xie', 'Daniel Xie 与社区贡献者', '', '', NULL, '', 0, 2019, 'idle', '["放置","编程","角色扮演"]', 120, 0.08, 'clicker', 'https://bitburner-official.github.io/', 0, 0, 0, 1, 0, 0, 1, 'long', 'hosted', '写脚本入侵服务器，在赛博朋克都市里慢慢变强', '一款以编程为核心的增量 RPG：打开终端、写脚本、管理服务器，在 2077 年的黑暗都市里扩张自己的黑客网络。', 'A programming-based incremental RPG: open the terminal, write scripts, manage servers, and grow a hacker network in a dark 2077 city.', '由 Daniel Xie 与社区贡献者制作，源码以 Apache-2.0（附加 Commons Clause）在 GitHub 发布。原页托管在 bitburner-official.github.io，不是即玩的作品。在即玩里直接打开原作。存档保存在浏览器本地，开玩不用登录。可选的 Steam 版不影响网页免费游玩。', 'Made by Daniel Xie and contributors; the source is Apache-2.0 with Commons Clause on GitHub. Hosted at bitburner-official.github.io; it is not a Jiwan original. It opens here. Saves stay in your browser; no account needed. The optional Steam edition is not required to play on the web.', 'assets/posters/bitburner.jpg', 1280, 800, 'center', '["assets/posters/bitburner.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -19, 1794880800000, 'Write scripts to hack servers and grow stronger in a cyberpunk city.', '', '', 1);
